import re, glob, os
A='MainProjects/Algebraic-Jacobian-Challenge/blueprint/src/chapters'
L='SubProjects/Line-Bundle-Comparison-Iso/blueprint/src/chapters'
def strip(src):
    return '\n'.join(re.sub(r'(?<!\\)%.*','',l) for l in src.splitlines())
def labels(p): return set(re.findall(r'\\label\{([^}]*)\}', strip(open(p).read())))
def refs(p):
    src=strip(open(p).read()); out=set()
    # handle multi-line uses blocks: normalize whitespace
    src2 = re.sub(r'\s+',' ',src)
    for pat in (r'\\uses\{([^}]*)\}', r'\\cref\{([^}]*)\}'):
        for m in re.findall(pat, src2):
            out |= {x.strip() for x in m.split(',') if x.strip()}
    return out
tgt='Picard_TensorObjSubstrate.tex'
lbc_l = labels(f'{L}/{tgt}')
ajc_other = set()
for f in glob.glob(f'{A}/*.tex'):
    if os.path.basename(f)!=tgt: ajc_other |= labels(f)
print("dangling:", sorted(refs(f'{L}/{tgt}') - lbc_l - ajc_other))
ajc_only = labels(f'{A}/{tgt}') - lbc_l
broken=[]
for f in glob.glob(f'{A}/*.tex'):
    if os.path.basename(f)==tgt: continue
    hit = refs(f) & ajc_only
    if hit: broken.append((os.path.basename(f), sorted(hit)))
print("broken:", broken)
print("dup:", sorted(lbc_l & ajc_other))
EOF

